-- Fields of NULL PL/pgSQL row variables keep their declared types; %ROWTYPE
-- variables have the table's row type.
create table tr (a int, b text, c numeric(5,2));
create type ct as (x int, y varchar(3));
create function f1() returns text language plpgsql as $$ declare r tr; begin return pg_typeof(r.a)::text || ',' || pg_typeof(r.b) || ',' || pg_typeof(r.c) || ',' || coalesce(r.a::text,'null'); end $$;
select f1();
create function f2() returns text language plpgsql as $$ declare r ct; begin return pg_typeof(r.x)::text || pg_typeof(r.y); end $$;
select f2();
create function f3() returns text language plpgsql as $$ declare r tr; begin return pg_typeof(r.zz); end $$;
select f3();
create function f4() returns text language plpgsql as $$ declare r record; begin return pg_typeof(r.a); end $$;
select f4();
create function f5() returns text language plpgsql as $$ declare r tr; begin r := null; return pg_typeof(r.c)::text || (r.c is null); end $$;
select f5();
create function f6() returns text language plpgsql as $$ declare r tr%rowtype; begin return pg_typeof(r)::text || pg_typeof(r.b); end $$;
select f6();
create function g1() returns text language plpgsql as $$ declare r ct; begin return r.x; end $$;
select g1();
create function g2() returns text language plpgsql as $$ declare r tr; begin return r.a; end $$;
select g2();
create function g3() returns text language plpgsql as $$ declare r ct; begin return pg_typeof(r.x); end $$;
select g3();
create function g4() returns text language plpgsql as $$ declare r ct; begin r.x := 1; return pg_typeof(r.x); end $$;
select g4();
create function g5() returns text language plpgsql as $$ declare r tr; begin return pg_typeof(r.a); end $$;
select g5();
create function g6() returns text language plpgsql as $$ declare r tr; begin return r.a + 1; end $$;
select g6();
create function g7() returns text language plpgsql as $$ declare r tr; x text; begin select pg_typeof(r.b) into x; return x; end $$;
select g7();
create function g8() returns text language plpgsql as $$ declare r tr; begin return pg_typeof(r); end $$;
select g8();
drop function f1,f2,f3,f4,f5,f6,g1,g2,g3,g4,g5,g6,g7,g8; drop table tr; drop type ct;
create table tq (a int, b text);
insert into tq values (1, 'x');
create function k1() returns text language plpgsql as $$ declare r tq%rowtype; begin select * into r from tq; return pg_typeof(r)::text || r::text || pg_typeof(r.a); end $$;
select k1();
create function k2() returns tq language plpgsql as $$ declare r tq%rowtype; begin r.a := 5; r.b := 'q'; return r; end $$;
select k2(), (k2()).b;
create function k3() returns text language plpgsql as $$ declare r tq%rowtype; begin r := row(2,'y'); return r::text || (r is null); end $$;
select k3();
create function k4() returns text language plpgsql as $$ declare r tq%rowtype; s tq; begin s := (3,'z'); r := s; return r::text; end $$;
select k4();
create function k5() returns setof tq language plpgsql as $$ declare r tq%rowtype; begin for r in select * from tq loop return next r; end loop; end $$;
select * from k5();
alter table tq add column c int;
select k1(), k2();
alter table tq drop column a;
select k2();
drop table tq cascade;
drop function k1(), k3(), k4();
